async function getChromePath() {
    // Harbor Portable supplies its verified browser explicitly. A broken bundle
    // must not fall back to a host installation or an automatic download.
    if (Object.hasOwn(process.env, 'HARBOR_BUNDLED_CHROMIUM')) {
        const bundled = process.env.HARBOR_BUNDLED_CHROMIUM;
        if (!isAbsolute(bundled)) {
            throw new Error('Harbor bundled Chromium needs an absolute executable path');
        }
        let info;
        try { info = await fs.stat(bundled); }
        catch { throw new Error('Harbor bundled Chromium is missing: repair the browser component'); }
        if (!info.isFile()) {
            throw new Error('Harbor bundled Chromium is not an executable file');
        }
        return bundled;
    }
